    output.resize(n);
    if (n == 0) return;

    #pragma omp parallel
    {
        const int T = omp_get_num_threads();
        const int tid = omp_get_thread_num();

        // Allocate per-call shared arrays inside the parallel region, but without static storage.
        // 'shared' ensures all threads see the same vectors; allocation done by a single thread.
        std::vector<long long> chunkSum;
        std::vector<long long> offsetRight;

        #pragma omp single
        {
            chunkSum.assign(T, 0);
            offsetRight.assign(T, 0);
        }

        // Make these vectors shared among threads by referencing the single-allocated instances.
        // Use pointers to avoid creating per-thread copies.
        long long *chunkSumPtr = nullptr;
        long long *offsetRightPtr = nullptr;

        #pragma omp single
        {
            chunkSumPtr = chunkSum.data();
            offsetRightPtr = offsetRight.data();
        }

        // Broadcast pointers to all threads safely.
        #pragma omp barrier
        // After barrier, chunkSumPtr/offsetRightPtr are still private and nullptr in other threads.
        // We must share them explicitly.
        // Easiest: use shared variables declared outside of the parallel region is not allowed here.
        // Instead, redo with omp single copying into shared through a static is unsafe.
        // So we avoid pointers and use a different approach:
    }

    // Re-enter with correct shared allocation using omp parallel with shared vectors declared outside.
    // (This remains within the same function call; these are stack objects, safe and race-free.)
    std::vector<long long> chunkSum;
    std::vector<long long> offsetRight;

    #pragma omp parallel shared(chunkSum, offsetRight)
    {
        const int T = omp_get_num_threads();
        const int tid = omp_get_thread_num();

